export type PackagesConfig = {
    registries?: Record<string, string>;
    css?: string[];
    provider?: string;
    ssr?: boolean;
    isolation?: 'page' | 'frame';
};
export type IslandImport = {
    local: string;
    pkg: string;
    imported: string;
};
export type IslandSpec = {
    id: string;
    pagePath: string;
    kind: 'inline' | 'snippet';
    imports: IslandImport[];
    module: string;
};
export type Installer = 'local' | 'npm-ci' | 'prepared';
export type PackageManagerBinaries = {
    pnpm?: Record<string, string>;
};
export type ExpectedHashes = {
    depsHash: string;
    islandsHash: string;
};
export type BuildInput = {
    docsRoot: string;
    packages: PackagesConfig;
    islands: IslandSpec[];
    snippetFiles: Record<string, string>;
    outDir: string;
    installer: Installer;
    registryTokens?: Record<string, string>;
    packageManagers?: PackageManagerBinaries;
    renderMemoryLimitBytes?: number;
    expected?: ExpectedHashes;
};
export type BuildDiagnostic = {
    level: 'error' | 'warning';
    code: string;
    message: string;
    pkg?: string;
};
export type ManifestFile = {
    path: string;
    bytes: number;
    gzipBytes: number;
    integrity: string;
};
export type ManifestIsland = {
    entry: string;
    prefix: string;
    html?: string;
    ssrMs?: number;
    css?: ManifestStylesheet[];
};
export type ManifestStylesheet = {
    path: string;
    integrity: string;
    bytes: number;
};
export type ClientAccess = {
    version: 1;
    files: Record<string, string[]>;
    globalFiles: string[];
};
export type PackageBuildManifest = {
    version: 1;
    builderVersion: string;
    buildId: string;
    depsHash: string;
    islandsHash: string;
    react: {
        version: string;
        domVersion: string;
    };
    packages: Record<string, {
        version: string;
    }>;
    css: ManifestStylesheet[];
    clientAccess: ClientAccess;
    islands: Record<string, ManifestIsland>;
    files: ManifestFile[];
    diagnostics: BuildDiagnostic[];
};
export type BuildStats = {
    installMs: number;
    bundleMs: number;
    renderMs: number;
    totalMs: number;
    clientBytes: number;
    clientGzipBytes: number;
    serverBytes: number;
    islandClientGzipBytes: Record<string, number>;
    reactDirs: {
        react: string[];
        'react-dom': string[];
    };
};
export type BuildResult = {
    ok: boolean;
    manifest: PackageBuildManifest;
    stats: BuildStats;
    localFiles: string[];
    missingLocalFiles: string[];
};
